INSERT INTO places (id, name, tagline, category_id, region_id, area, description, best_time, hours, fee, duration, latitude, longitude, featured, sort_order) VALUES
  ('tanah-lot', 'Tanah Lot', 'Sea temple on a rock at sunset', 'temple', 'west', 'Beraban, Tabanan', 'One of Bali’s six key sea temples, Pura Tanah Lot sits on a rocky outcrop that becomes an island at high tide. Built in the 16th century and dedicated to the sea god Dewa Baruna, it is the island’s most photographed sunset spot.', 'Late afternoon, low tide', '7:00 am – 7:00 pm', '≈ IDR 75,000', '2 hours', -8.6212, 115.0868, 1, 0),
  ('uluwatu', 'Uluwatu Temple', 'Clifftop temple and Kecak fire dance', 'temple', 'south', 'Pecatu, Bukit Peninsula', 'Pura Luhur Uluwatu is perched on a 70-metre cliff above the Indian Ocean. Each evening the amphitheatre beside it hosts the Kecak fire dance, a chanted retelling of the Ramayana performed against the sunset.', '4:00 pm – sunset', '7:00 am – 7:00 pm', '≈ IDR 50,000 (Kecak extra)', '3 hours', -8.8291, 115.0849, 1, 1),
  ('tirta-empul', 'Tirta Empul', 'Holy spring water temple', 'temple', 'ubud', 'Tampaksiring, Gianyar', 'Founded over a thousand years ago around a natural spring, Tirta Empul is where Balinese Hindus come for melukat, a ritual purification under a row of carved water spouts.', 'Early morning', '8:00 am – 6:00 pm', '≈ IDR 75,000', '1.5 hours', -8.4153, 115.3153, 0, 2),
  ('lempuyang', 'Lempuyang Temple', 'The Gates of Heaven', 'temple', 'east', 'Karangasem', 'Pura Lempuyang Luhur is one of Bali’s oldest and most sacred temples. Its split gateway frames Mount Agung, and a long stairway continues up through forest to six more temples near the summit.', 'Sunrise on a clear day', '7:00 am – 5:00 pm', 'Donation + shuttle', '3 hours', -8.3906, 115.6313, 1, 3),
  ('ulun-danu', 'Ulun Danu Beratan', 'Lake temple in the misty highlands', 'temple', 'highlands', 'Bedugul, Tabanan', 'Dedicated to the lake goddess Dewi Danu, this 17th-century water temple seems to float on Lake Beratan. Cool air and mountain mist make it a refreshing break from the coast.', 'Morning, before clouds roll in', '7:00 am – 6:00 pm', '≈ IDR 75,000', '1.5 hours', -8.2752, 115.1668, 0, 4),
  ('besakih', 'Besakih Temple', 'The Mother Temple of Bali', 'temple', 'east', 'Slopes of Mount Agung', 'Pura Besakih is a complex of more than 80 temples climbing the slopes of Mount Agung, Bali’s highest and holiest volcano. It is the spiritual centre of Balinese Hinduism.', 'Morning', '8:00 am – 5:00 pm', '≈ IDR 60,000', '2 hours', -8.3742, 115.4511, 0, 5),
  ('tegallalang', 'Tegallalang Rice Terraces', 'Iconic green terraces north of Ubud', 'nature', 'ubud', 'Tegallalang, Gianyar', 'Steep, sculpted rice terraces irrigated by the ancient subak system. Paths wind down through the valley, with jungle swings and cafés along the rim.', 'Sunrise to 9:00 am', '8:00 am – 6:00 pm', 'Small entry + donations', '1.5 hours', -8.4312, 115.2793, 1, 6),
  ('jatiluwih', 'Jatiluwih Rice Terraces', 'UNESCO-listed subak landscape', 'nature', 'highlands', 'Penebel, Tabanan', 'Over 600 hectares of terraces beneath Mount Batukaru, recognised by UNESCO as part of Bali’s cultural landscape. Far larger and calmer than Tegallalang.', 'Morning, Feb–Apr for green fields', '7:00 am – 6:00 pm', '≈ IDR 50,000', '2 hours', -8.37, 115.1316, 0, 7),
  ('monkey-forest', 'Sacred Monkey Forest', 'Jungle temples and 1,200 macaques', 'nature', 'ubud', 'Ubud Town', 'A sanctuary of ancient banyan trees and moss-covered temples in the heart of Ubud, home to a large troop of long-tailed macaques.', 'Morning', '9:00 am – 6:00 pm', '≈ IDR 80,000', '1.5 hours', -8.5188, 115.2585, 0, 8),
  ('mount-batur', 'Mount Batur Sunrise', 'Hike an active volcano before dawn', 'nature', 'highlands', 'Kintamani, Bangli', 'A two-hour pre-dawn climb up a 1,717 m active volcano rewards hikers with sunrise over Lake Batur and Mount Agung, plus breakfast cooked in volcanic steam.', 'Dry season, 4:00 am start', 'Treks start 3:30–4:00 am', 'Guided tour required', '6 hours', -8.2422, 115.375, 1, 9),
  ('campuhan', 'Campuhan Ridge Walk', 'Easy ridge trail above two rivers', 'nature', 'ubud', 'Ubud Town', 'A paved two-kilometre path along a grassy ridge between two river valleys, starting near Pura Gunung Lebah. A gentle, free introduction to Ubud’s countryside.', 'Sunrise or 4:00 pm', 'Open 24 hours', 'Free', '1–2 hours', -8.5036, 115.2547, 0, 10),
  ('tukad-cepung', 'Tukad Cepung Waterfall', 'Light beams inside a canyon cave', 'waterfall', 'highlands', 'Tembuku, Bangli', 'A waterfall hidden inside a narrow canyon, where shafts of sunlight pour through a gap in the rock on clear mornings.', '9:00 – 10:30 am', '8:00 am – 5:00 pm', '≈ IDR 20,000', '1 hour', -8.4365, 115.3878, 0, 11),
  ('tegenungan', 'Tegenungan Waterfall', 'Powerful falls close to Ubud', 'waterfall', 'ubud', 'Kemenuh, Gianyar', 'A wide, thundering waterfall 20 minutes from Ubud, easily reached by a staircase into a jungle valley with swimming at the base when the river is calm.', 'Early morning', '7:00 am – 6:00 pm', '≈ IDR 20,000', '1 hour', -8.5754, 115.2898, 0, 12),
  ('sekumpul', 'Sekumpul Waterfall', 'Bali’s most dramatic cascade', 'waterfall', 'north', 'Sawan, Buleleng', 'A cluster of seven waterfalls dropping 80 m into a lush amphitheatre in North Bali. The descent through clove and coffee plantations is part of the adventure.', 'Dry season mornings', '7:00 am – 5:00 pm', 'Guide fee applies', '3 hours', -8.1736, 115.1823, 0, 13),
  ('kelingking', 'Kelingking Beach', 'The T-Rex cliff on Nusa Penida', 'beach', 'nusa', 'Nusa Penida', 'A headland shaped like a dinosaur’s head guards a perfect white-sand cove. The clifftop view is unforgettable; the steep scramble down is for the fit and sure-footed.', 'Morning, calm seas', 'Daylight', 'Island levy + parking', 'Full day trip', -8.7503, 115.4746, 1, 14),
  ('seminyak', 'Seminyak Beach', 'Sunsets, beach clubs and boutiques', 'beach', 'south', 'Seminyak', 'A long stretch of golden sand lined with bean bags, beach clubs and some of Bali’s best restaurants. Waves suit beginner surfers; currents can be strong.', 'Sunset', 'Open 24 hours', 'Free', 'Half day', -8.6913, 115.1563, 0, 15),
  ('padang-padang', 'Padang Padang Beach', 'Hidden cove through a rock crevice', 'beach', 'south', 'Pecatu, Bukit Peninsula', 'A small, beautiful beach reached through a narrow passage in the cliffs. Calm in the morning, it is also home to a world-famous reef break for experienced surfers.', 'Morning', '7:00 am – 7:00 pm', '≈ IDR 15,000', '3 hours', -8.8113, 115.1018, 0, 16),
  ('nusa-dua', 'Nusa Dua', 'Calm water and resort promenade', 'beach', 'south', 'Nusa Dua', 'A manicured resort enclave with gentle reef-protected water, ideal for families. A paved beachwalk links the hotels to the Water Blow viewpoint.', 'Morning', 'Open 24 hours', 'Free', 'Half day', -8.8008, 115.2335, 0, 17),
  ('amed', 'Amed & Tulamben', 'Black-sand bays and a WWII wreck', 'beach', 'east', 'Karangasem coast', 'A laid-back strip of fishing villages with excellent snorkelling straight off the beach. Nearby Tulamben hosts the USAT Liberty wreck, one of the world’s most accessible dive sites.', 'Apr – Nov, calm mornings', 'Daylight', 'Free (dives extra)', '1–2 days', -8.3366, 115.662, 0, 18),
  ('ubud-palace', 'Ubud Palace & Market', 'Royal courtyard and evening dance', 'culture', 'ubud', 'Ubud Town', 'Puri Saren Agung, the former royal palace of Ubud, faces the town’s bustling art market. In the evening the palace courtyard hosts traditional Legong and Barong dance performances.', 'Morning for market, 7:30 pm for dance', '8:00 am – 7:00 pm', 'Free (dance tickets extra)', '2–3 hours', -8.5069, 115.2625, 0, 19),
  ('gwk', 'Garuda Wisnu Kencana', 'A 121 m monument to Vishnu', 'culture', 'south', 'Ungasan, Bukit Peninsula', 'A cultural park carved out of limestone cliffs, crowned by one of the world’s tallest statues: Vishnu riding the mythical bird Garuda. Daily dance shows run in the amphitheatre.', 'Late afternoon', '8:00 am – 8:00 pm', '≈ IDR 125,000', '2 hours', -8.8104, 115.1676, 0, 20),
  ('sidemen', 'Sidemen Valley', 'Bali as it used to be', 'culture', 'east', 'Karangasem', 'A quiet valley of rice fields, weaving villages and river walks beneath Mount Agung. Ideal for slow travel, cycling and learning traditional songket weaving.', 'Any morning', 'Open 24 hours', 'Free', '1 day', -8.4767, 115.4435, 0, 21);
