INSERT INTO place_tips (place_id, body, sort_order) VALUES
  ('tanah-lot', 'Arrive by 4:30 pm to find a good sunset viewpoint.', 0),
  ('tanah-lot', 'At low tide you can walk to the base and receive a blessing.', 1),
  ('tanah-lot', 'Only worshippers may climb into the temple itself.', 2),
  ('uluwatu', 'Resident monkeys grab sunglasses, phones and hats — keep them packed away.', 0),
  ('uluwatu', 'Kecak tickets sell out in high season; buy early in the afternoon.', 1),
  ('uluwatu', 'Sarongs are provided at the entrance.', 2),
  ('tirta-empul', 'Bring a change of clothes if you plan to join the purification.', 0),
  ('tirta-empul', 'Follow the order of the spouts and skip those reserved for funerary rites.', 1),
  ('tirta-empul', 'Early morning is quieter and more reverent.', 2),
  ('lempuyang', 'Photo queues at the gate can exceed two hours — arrive before sunrise.', 0),
  ('lempuyang', 'The famous “reflection” is a mirror trick; the real view is just as good.', 1),
  ('lempuyang', 'A shuttle runs from the car park to the main gate.', 2),
  ('ulun-danu', 'Bring a light jacket — it is noticeably cooler at 1,200 m.', 0),
  ('ulun-danu', 'Combine with the Bedugul fruit market and Jatiluwih.', 1),
  ('besakih', 'Use the official visitor centre; ignore unofficial “guides” at the gate.', 0),
  ('besakih', 'Some inner courtyards are closed to visitors during ceremonies.', 1),
  ('tegallalang', 'Arrive before 8 am for soft light and few crowds.', 0),
  ('tegallalang', 'Farmers collect small donations at bridges — keep coins handy.', 1),
  ('tegallalang', 'Wear shoes with grip; paths are muddy after rain.', 2),
  ('jatiluwih', 'Try the local red rice tea.', 0),
  ('jatiluwih', 'Pair with Ulun Danu Beratan in a highlands day trip.', 1),
  ('monkey-forest', 'Do not carry food or plastic bags.', 0),
  ('monkey-forest', 'Avoid eye contact and let monkeys come to you — never feed them.', 1),
  ('mount-batur', 'Hotel pickups are around 2:00 am from Ubud.', 0),
  ('mount-batur', 'A licensed local guide is required on the mountain.', 1),
  ('mount-batur', 'Bring a warm layer, a headlamp and proper shoes.', 2),
  ('campuhan', 'Go at sunrise or late afternoon — there is little shade.', 0),
  ('campuhan', 'Carry water.', 1),
  ('tukad-cepung', 'Arrive 9–10 am for the light beams.', 0),
  ('tukad-cepung', 'Expect to get wet; bring a dry bag.', 1),
  ('tegenungan', 'Visit early to beat tour groups.', 0),
  ('tegenungan', 'Skip swimming after heavy rain.', 1),
  ('sekumpul', 'A local guide is required for the lower trail.', 0),
  ('sekumpul', 'Allow a full day from the south.', 1),
  ('kelingking', 'Fast boats run from Sanur (about 45 minutes).', 0),
  ('kelingking', 'Strong currents — swimming at the cove is not advised.', 1),
  ('kelingking', 'Allow 1 hour each way if hiking down.', 2),
  ('seminyak', 'Swim only between the red-and-yellow flags.', 0),
  ('seminyak', 'Book popular beach clubs in advance.', 1),
  ('padang-padang', 'Arrive early — the beach is small.', 0),
  ('padang-padang', 'Watch for reef at low tide.', 1),
  ('nusa-dua', 'Great for kids and paddleboarding.', 0),
  ('nusa-dua', 'Water Blow is best at high tide with big swell.', 1),
  ('amed', 'Bring reef shoes — beaches are pebbly.', 0),
  ('amed', 'Dive the wreck at dawn before the crowds.', 1),
  ('ubud-palace', 'Bargain with a smile — start around half the first price.', 0),
  ('ubud-palace', 'Dance tickets are sold at the gate from late afternoon.', 1),
  ('gwk', 'Go late afternoon and continue to Uluwatu for sunset.', 0),
  ('gwk', 'Shuttle carts help with the long walks.', 1),
  ('sidemen', 'Stay a night or two to enjoy it properly.', 0),
  ('sidemen', 'Hire a local guide for village trekking.', 1);
