INSERT INTO guide_tips (section, icon, title, body, sort_order) VALUES
  ('essentials', 'arrival', 'Arrival & tourist levy', 'Most visitors need a visa on arrival or e-VOA, and foreign tourists pay Bali’s IDR 150,000 tourist levy. Check current rules before you fly.', 0),
  ('essentials', 'weather', 'When to go', 'Dry season runs April to October. November to March is wet, greener and quieter, with short heavy downpours.', 1),
  ('essentials', 'car', 'Getting around', 'Use the Grab or Gojek apps for rides, or hire a private driver for day trips. Traffic in the south is slow — plan for it.', 2),
  ('essentials', 'scooter', 'Scooters', 'Only ride with an International Driving Permit valid for motorcycles and always wear a helmet. Check your insurance covers it.', 3),
  ('essentials', 'boat', 'Islands', 'Fast boats to Nusa Penida and Nusa Lembongan leave from Sanur. Book with operators that provide life jackets.', 4),
  ('essentials', 'waterfall', 'Stay healthy', 'Drink bottled or refilled filtered water, use reef-safe sunscreen and pack insect repellent.', 5),
  ('etiquette', 'temple', 'Dress for temples', 'Cover shoulders and knees and wear a sarong and sash. Most temples lend them at the entrance.', 0),
  ('etiquette', 'respect', 'Mind the offerings', 'Small palm-leaf canang sari are placed on pavements and doorsteps daily. Step around them, never on them.', 1),
  ('etiquette', 'info', 'Right hand, no heads', 'Give and receive with your right hand, and never touch anyone’s head — it is considered sacred.', 2),
  ('etiquette', 'calendar', 'Nyepi, the Day of Silence', 'Each March the whole island shuts down for 24 hours, including the airport. Visitors must stay inside their hotel.', 3),
  ('etiquette', 'culture', 'Ceremonies are not shows', 'You will often meet processions on the road. Pull over, stay quiet and ask before taking photos.', 4);
